const b = $input.first().json.body ?? $input.first().json;
const errors = [];
for (const k of ['claimId', 'visitId', 'submittedBy', 'idempotencyKey']) if (!b[k] || typeof b[k] !== 'string') errors.push(`${k} is required`);
if (!Number.isInteger(b.draftVersion)) errors.push('draftVersion must be an integer');
if (!Array.isArray(b.decisions) || !b.decisions.length) errors.push('decisions must be a non-empty array');
return [{ json: { valid: errors.length === 0, errors, body: b } }];

// The server never trusts the browser: every code in the STORED draft needs exactly one explicit decision.
const body = $('Validate payload').first().json.body;
const stored = $input.first().json;
const short = (httpStatus, code, message) => [{ json: { ok: false, short: true, httpStatus, code, message, details: [] } }];
if (!stored.claim_id) return short(404, 'not_found', 'Claim not found.');
if (body.draftVersion !== stored.latest_version) return short(409, 'stale_draft', 'This draft was regenerated. Reload the claim and review the new draft.');

const storedCodes = stored.payload.codes;
const byId = new Map(storedCodes.map((c) => [c.id, c]));
const seen = new Set();
const replaced = [];
const errors = [];
for (const d of body.decisions) {
  const sc = byId.get(d.codeId);
  if (!sc) { errors.push(`Unknown code id ${d.codeId}.`); continue; }
  if (seen.has(d.codeId)) { errors.push(`More than one decision was sent for ${sc.code}.`); continue; }
  seen.add(d.codeId);
  if (d.decision !== 'approved' && d.decision !== 'rejected') { errors.push(`Code ${sc.code} has no explicit decision.`); continue; }
  if (d.code !== sc.code) {
    if (d.replacedFrom !== sc.code) errors.push(`Replacement for ${sc.code} must state replacedFrom.`);
    replaced.push(String(d.code).toUpperCase());
  } else if (d.decision === 'approved') {
    const badGates = sc.validation.filter((g) => g.status === 'failed' || g.status === 'unavailable');
    if (badGates.length) errors.push(`Code ${sc.code} cannot be approved: ${badGates.map((g) => `${g.label} ${g.status}`).join(', ')}.`);
  }
}
for (const sc of storedCodes) if (!seen.has(sc.id)) errors.push(`Code ${sc.code} has no decision.`);
if (!body.decisions.some((d) => d.decision === 'approved')) errors.push('At least one approved code is required to submit a claim.');
const runId = `run_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
return [{ json: { ok: errors.length === 0, short: false, errors, replaced, body, stored, run_id: runId } }];

const s = $('Structural validation').first().json;
if (s.short) return [{ json: s }];
const cat = $input.first().json;
const errors = [...s.errors];
const decisions = s.body.decisions;
const claim = s.stored.payload;
const approvedReplaced = decisions.filter((d) => d.decision === 'approved' && d.replacedFrom);
if (approvedReplaced.length) {
  if (cat.error) errors.push('Replacement codes could not be verified: the code catalog did not respond.');
  else for (const d of approvedReplaced) if (!cat.codes?.[String(d.code).toUpperCase()]) errors.push(`Replacement code ${d.code} was not found in the code catalog.`);
}
const approved_codes = decisions.filter((d) => d.decision === 'approved').map((d) => {
  const sc = claim.codes.find((c) => c.id === d.codeId);
  const cc = d.replacedFrom ? cat.codes?.[String(d.code).toUpperCase()] : null;
  return { code: d.code, category: cc?.category ?? sc.category, description: cc?.description ?? sc.description, replaced_from: d.replacedFrom ?? null };
});
return [{ json: {
  ok: errors.length === 0, httpStatus: 422, code: 'validation_rejected',
  message: errors.length ? `Final validation failed: ${errors[0]}` : '', details: errors,
  body: s.body, stored: s.stored, run_id: s.run_id, approved_codes,
} }];

const v = $('Finalize validation').first().json;
const claim = v.stored.payload;
return [{ json: {
  claim_id: claim.id, visit_id: claim.visitId,
  patient: { id: claim.patientId, name: claim.patientName },
  provider: { id: claim.doctorId, name: claim.doctorName },
  payer: claim.payer, facility: claim.facility, note_signed_at: claim.noteSignedAt,
  submitted_by: v.body.submittedBy, idempotency_key: `submit_${claim.visitId}`,
  codes: v.approved_codes,
} }];

const v = $('Finalize validation').first().json;
const sub = $('Submit to clearinghouse').first().json;
const claim = v.stored.payload;
const body = v.body;
const now = new Date().toISOString();
const draftLabel = `Draft v${v.stored.latest_version}`;
const rows = [];
const A = (event, entity, o = {}) => rows.push({
  ts: now, actor: o.actor ?? body.submittedBy, actor_type: o.actor_type ?? 'doctor', event, entity,
  claim_id: claim.id, visit_id: claim.visitId, patient_id: claim.patientId, code: o.code ?? null,
  previous_value: o.previous ?? null, new_value: o.next ?? null, run_id: v.run_id,
  version: o.version === undefined ? draftLabel : o.version, metadata: o.metadata ?? {},
});
for (const d of body.decisions) {
  const sc = claim.codes.find((c) => c.id === d.codeId);
  if (d.replacedFrom) A('Doctor edited code', `Code ${d.code}`, { code: d.code, previous: d.replacedFrom, next: d.code, metadata: { ai_proposed: sc?.code ?? d.replacedFrom, decision_after_edit: d.decision } });
  A(d.decision === 'approved' ? 'Doctor approved code' : 'Doctor rejected code', `Code ${d.code}`, {
    code: d.code, previous: 'pending', next: d.decision,
    metadata: { decision_scope: 'single code', ...(d.reason ? { reason: d.reason } : {}), ...(d.note ? { note: d.note } : {}), ...(sc?.complexity === 'high' ? { high_complexity_review: 'explicit decision recorded' } : {}) },
  });
}
const approved = body.decisions.filter((d) => d.decision === 'approved');
A('Final claim version submitted', `Claim ${claim.id}`, {
  actor: 'Workflow Engine', actor_type: 'system', version: null,
  metadata: { edi_control_number: String(sub.control_number), approved_codes: v.approved_codes.map((c) => c.code).join(', '), approved: String(approved.length), rejected: String(body.decisions.length - approved.length) },
});
const changed = body.decisions.filter((d) => d.decision === 'rejected' || d.replacedFrom).length;
return [{ json: {
  claim_id: claim.id, visit_id: claim.visitId, run_id: v.run_id, edi_control_number: String(sub.control_number),
  submitted_at: now, submitted_by: body.submittedBy,
  submitted_payload: { claim_id: claim.id, approved_codes: v.approved_codes, decisions: body.decisions, from_draft: v.stored.latest_version },
  audit_rows: rows, proposed_count: body.decisions.length, changed_count: changed,
} }];
